import { MagazineBlocksLocalized } from "../types";

export const localized: MagazineBlocksLocalized = (window as any)
	._MAGAZINE_BLOCKS_;

// Legacy/demo-imported data can store categories_color as an indexed object instead of an array.
const categoriesColor = localized?.configs?.["global-styles"]?.categories_color;
if (categoriesColor && !Array.isArray(categoriesColor)) {
	localized.configs["global-styles"].categories_color =
		Object.values(categoriesColor);
}
