import { RichText } from "@wordpress/block-editor";
import { BlockSaveProps } from "@wordpress/blocks";
import React from "react";
import { cn } from "../../../../utils";
import metadata from "./../../block.json";

/**
 * Frozen pre-migration save function for paragraph block.
 *
 * @param {BlockSaveProps<any>} props Block properties.
 * @return {React.JSX.Element|null} Save element.
 */
const Save: React.ComponentType<BlockSaveProps<any>> = (props) => {
	const {
		attributes: { cssID, clientId, className, text, typography },
	} = props;

	if (RichText.isEmpty(text)) {
		return null;
	}

	return (
		<p
			id={cssID ?? undefined}
			className={cn(
				`mzb-paragraph mzb-paragraph-${clientId}`,
				typography?._className,
				className
			)}
		>
			{<RichText.Content value={text} />}
		</p>
	);
};

const v1 = {
	apiVersion: 1,
	attributes: {
		...metadata.attributes,
	},
	supports: metadata.supports,
	save: Save,
};

export default v1;
