import {
	Tab,
	TabList,
	TabPanel,
	TabPanels,
	Tabs,
	Text,
} from "@chakra-ui/react";
import { __ } from "@wordpress/i18n";
import React from "react";
import AdvancedControls from "../../../components/common/AdvancedControls";
import useDevice from "../../../hooks/useDevice";
import InspectorTabs, {
	AdvancedInspectorControls,
	GeneralInspectorControls,
	StyleInspectorControls,
} from "../../../components/common/InspectorTabs";
import Panel from "../../../components/common/Panel";
import ResponsiveControls from "../../../components/common/ResponsiveControls";
import ZStack from "../../../components/common/ZStack";
import {
	AlignCenter,
	AlignLeft,
	AlignRight,
	AlignSpaceBetween,
} from "../../../components/icons/Icons";
import {
	Border,
	BoxShadow,
	ColorPicker,
	PopoverDrawer,
	Slider,
	ToggleButton,
	ToggleButtonGroup,
} from "../../../controls";
import Reset from "../../../controls/common/Reset";

type Props = {
	attributes: any;
	setAttributes: (attributes: any) => void;
};

const InspectorControls: React.ComponentType<Props> = (props) => {
	const {
		attributes: {
			alignment,
			columnGap,
			backgroundColor,
			boxShadow,
			border,

			blockPadding,
			blockMargin,
			hideOnDesktop,
			hideOnTablet,
			hideOnMobile,
		},
		setAttributes,
	} = props;

	const { device } = useDevice();
	const isSpaceBetween = alignment?.[device] === "space-between";

	return (
		<>
			<InspectorTabs />
			<GeneralInspectorControls>
				<Panel title={__("Layout", "magazine-blocks")} initialOpen>
					<Slider
						// @ts-ignore
						onChange={(val) => setAttributes({ columnGap: val })}
						label={__("Column Gap", "magazine-blocks")}
						units={["px", "em", "%"]}
						responsive={true}
						min={0}
						max={40}
						value={columnGap}
						resetAttributeKey="columnGap"
						isDisabled={isSpaceBetween}
					/>
					<ToggleButtonGroup
						value={alignment}
						onChange={(v) => setAttributes({ alignment: v })}
						label={__("Icon Alignment", "magazine-blocks")}
						responsive
						groupProps={{
							sx: {
								".chakra-button": {
									minH: "32px",
									svg: {
										w: 6,
										h: 6,
									},
								},
							},
						}}
					>
						<ToggleButton
							value="left"
							title={__("Left", "magazine-blocks")}
						>
							<AlignLeft />
						</ToggleButton>
						<ToggleButton
							value="center"
							title={__("Center", "magazine-blocks")}
						>
							<AlignCenter />
						</ToggleButton>
						<ToggleButton
							value="right"
							title={__("Right", "magazine-blocks")}
						>
							<AlignRight />
						</ToggleButton>
						<ToggleButton
							value="space-between"
							title={__("Space Between", "magazine-blocks")}
						>
							<AlignSpaceBetween />
						</ToggleButton>
					</ToggleButtonGroup>
					{isSpaceBetween && (
						<Text fontSize="xs" color="gray.500" mt="2">
							{__(
								"Column Gap is disabled because Space Between already spreads icons to fill the row.",
								"magazine-blocks"
							)}
						</Text>
					)}
				</Panel>
			</GeneralInspectorControls>
			<StyleInspectorControls>
				<Panel
					title={__("Social Icons", "magazine-blocks")}
					initialOpen
				>
					<PopoverDrawer
						label={__("Background Color", "magazine-blocks")}
						trigger={(props) => (
							<PopoverDrawer.Trigger {...props}>
								<ZStack
									items={[
										{
											color: backgroundColor,
											id: "backgroundColor",
										},
									]}
								/>
							</PopoverDrawer.Trigger>
						)}
						closeOnFocusOutside
					>
						<Tabs position="relative">
							<TabList>
								<Tab>{__("Normal", "magazine-blocks")}</Tab>
							</TabList>
							<TabPanels>
								<TabPanel>
									<Reset
										saved={backgroundColor}
										resetKey="backgroundColor"
										onReset={(v) => {
											setAttributes({
												backgroundColor: v,
											});
										}}
										buttonProps={{
											position: "absolute",
											top: "12px",
											right: "10px",
										}}
									/>
									<ColorPicker
										value={backgroundColor}
										onChange={(v) =>
											setAttributes({
												backgroundColor: v,
											})
										}
									/>
								</TabPanel>
							</TabPanels>
						</Tabs>
					</PopoverDrawer>
				</Panel>
				<Panel title={__("Border & Shadow", "magazine-blocks")}>
					<Border
						value={border}
						onChange={(v) => {
							setAttributes({
								border: v,
							});
						}}
						resetAttributeKey="border"
					/>
					<BoxShadow
						resetAttributeKey="boxShadow"
						value={boxShadow}
						onChange={(val) =>
							setAttributes({
								boxShadow: val,
							})
						}
					/>
				</Panel>
			</StyleInspectorControls>
			<AdvancedInspectorControls>
				<AdvancedControls
					blockMargin={blockMargin}
					setAttributes={setAttributes}
					blockPadding={blockPadding}
				/>
				<ResponsiveControls
					{...{
						hideOnDesktop,
						hideOnTablet,
						hideOnMobile,
						setAttributes,
					}}
				/>
			</AdvancedInspectorControls>
		</>
	);
};

export default InspectorControls;
