import { __, sprintf } from "@wordpress/i18n";
import React, { useState } from "react";
import { Select, ToggleButton, ToggleButtonGroup } from "../../controls";

export interface TaxonomyFilterOption {
	label: string;
	value: string;
}

/** Props configuring an Include/Exclude taxonomy filter toggle over a single-select and multi-select pair. */
export interface TaxonomyFilterControlProps {
	label: string;
	includeValue: string;
	excludeValue: string[];
	includeOptions: TaxonomyFilterOption[];
	excludeOptions: TaxonomyFilterOption[];
	onIncludeChange: (value: string) => void;
	onExcludeChange: (value: string[]) => void;
}

type FilterMode = "include" | "exclude";

/** Renders an Include/Exclude toggle that swaps between a single-select (include) and multi-select (exclude) for a taxonomy. */
const TaxonomyFilterControl: React.FC<TaxonomyFilterControlProps> = ({
	label,
	includeValue,
	excludeValue,
	includeOptions,
	excludeOptions,
	onIncludeChange,
	onExcludeChange,
}) => {
	const [mode, setMode] = useState<FilterMode>(() => {
		const hasMeaningfulInclude = includeValue && includeValue !== "all";
		const hasExclude = excludeValue && excludeValue.length > 0;
		return hasExclude && !hasMeaningfulInclude ? "exclude" : "include";
	});

	// Switching modes clears the other field so only one filter stays meaningfully active at a time.
	const handleModeChange = (nextMode: FilterMode) => {
		setMode(nextMode);
		if (nextMode === "include") {
			onExcludeChange([]);
		} else {
			onIncludeChange("all");
		}
	};

	return (
		<>
			<ToggleButtonGroup
				value={mode}
				onChange={(v) => handleModeChange(v as FilterMode)}
				label={label}
			>
				<ToggleButton value="include">
					{__("Include", "magazine-blocks")}
				</ToggleButton>
				<ToggleButton value="exclude">
					{__("Exclude", "magazine-blocks")}
				</ToggleButton>
			</ToggleButtonGroup>
			{mode === "include" ? (
				<Select
					value={includeValue}
					onChange={(val) => onIncludeChange(val as string)}
					label={sprintf(__("Include %s", "magazine-blocks"), label)}
					options={includeOptions}
				/>
			) : (
				<Select
					isMulti
					value={excludeValue}
					onChange={(val) => onExcludeChange(val as string[])}
					label={sprintf(__("Exclude %s", "magazine-blocks"), label)}
					options={excludeOptions}
				/>
			)}
		</>
	);
};

export default TaxonomyFilterControl;
