import { cn, kebabToCamelCase, localized } from "@blocks/utils";
import { SVG } from "@wordpress/components";
import { createElement } from "@wordpress/element";
import { BlockSaveProps } from "@wordpress/blocks";
import parse from "html-react-parser";
import React from "react";
import { Element } from "../../../../components";
import metadata from "./../../block.json";

/**
 * Frozen icon renderer matching content saved while the Pro plugin was
 * active: Pro's own IconRenderer outputs the `mzb-icon` class, whereas the
 * free plugin's IconRenderer outputs `magazine-blocks-icon`. Content authored
 * under Pro fails validation once only the free plugin is active.
 */
const LegacyIconRenderer: React.FC<{ name?: string }> = ({ name }) => {
	if (!name) return null;

	const iconName = kebabToCamelCase(name);
	const icon =
		localized.icons.all?.[iconName] ?? localized.icons.all?.[name] ?? null;

	if (!icon) return null;

	const appliedProps = {
		width: 24,
		height: 24,
		...(parse(icon?.svg) as React.ReactElement)?.props,
		className: cn("mzb-icon"),
	};

	return createElement(SVG, appliedProps);
};

/**
 * Frozen pre-migration save function for icon block, matching content saved
 * with the `mzb-icon` legacy icon class.
 *
 * @param {BlockSaveProps<any>} props Block properties.
 * @return {React.JSX.Element} Save element.
 */
const Save: React.ComponentType<BlockSaveProps<any>> = (props) => {
	const {
		attributes: {
			icon,
			link,
			presets,
			contentHorizontalAlign,
			className,
			cssID,
			clientId,
		},
	} = props;

	return (
		<div
			id={cssID ? cssID : null}
			className={cn(
				`mzb-icon-block mzb-icon-${clientId}`,
				contentHorizontalAlign && `mzb-${contentHorizontalAlign}`,
				className
			)}
		>
			<Element
				tagName="a"
				htmlAttrs={{
					className: cn("mzb-outside-icon", "mzb-icon-link"),
					href: link && link.url ? link.url : null,
					target: link && link.newTab ? "_blank" : null,
					rel: link && link.newTab ? "noopener" : null,
				}}
			>
				<span
					className={cn(
						`mzb-icon-wrapper`,
						presets && `mzb-${presets}`,
						className
					)}
				>
					<LegacyIconRenderer name={icon} />
				</span>
			</Element>
		</div>
	);
};

const v2 = {
	apiVersion: 1,
	attributes: {
		...metadata.attributes,
	},
	supports: metadata.supports,
	save: Save,
};

export default v2;
