import { select } from "@wordpress/data";
import { Prettify } from "blocks/components/types";
import { EditProps } from "blocks/types";
import { useEffect } from "react";

const useClientId = (props: Prettify<EditProps<any>>) => {
	const { attributes, setAttributes, clientId } = props;

	useEffect(() => {
		const id = clientId.substring(0, 8);

		if (!attributes.clientId) {
			setAttributes({ clientId: id });
			return;
		}

		if (attributes.clientId === id) {
			return;
		}

		const { getClientIdsWithDescendants, getBlock } = select(
			"core/block-editor"
		) as any;

		const isDuplicate = getClientIdsWithDescendants().some(
			(otherClientId: string) =>
				otherClientId !== clientId &&
				getBlock(otherClientId)?.attributes?.clientId ===
					attributes.clientId
		);

		if (isDuplicate) {
			setAttributes({ clientId: id });
		}
	}, [clientId, attributes.clientId, setAttributes]);

	return { clientId: attributes.clientId };
};

export default useClientId;
