import { DEVICES } from "../../constants";
import { GeneratorArgs, ResponsiveCSS } from "../types";
import { meetsConditions, replacePlaceholders } from "../utils";

const isGradient = (color: string) =>
	color?.startsWith("linear-gradient") ||
	color?.startsWith("radial-gradient");

const borderCSS = (props: GeneratorArgs) => {
	const { settingValue, settingDef, blockName, blockID } = props;
	const styles = settingDef?.style;
	const css: ResponsiveCSS = {
		allDevice: [],
		desktop: [],
		tablet: [],
		mobile: [],
	};
	const tempCSS: ResponsiveCSS = {
		allDevice: [],
		desktop: [],
		tablet: [],
		mobile: [],
	};

	if (!styles) {
		return css;
	}

	const { type = "none", size, radius, color } = settingValue;

	for (const style of styles) {
		if (!meetsConditions(props.settings, style)) {
			continue;
		}

		const selector = replacePlaceholders(style.selector, {
			WRAPPER: `.mzb-${blockName}-${blockID}`,
		});

		for (const device in DEVICES) {
			let borderCSS = "";

			if ("none" !== type) {
				borderCSS += `border-style: ${type};`;

				if (color) {
					if (isGradient(color)) {
						borderCSS += `border-image: ${color} 1; border-image-slice: 1;`;
					} else {
						borderCSS += `border-color: ${color};`;
					}
				}

				const deviceSize = size?.[device];
				const hasSizeValues = ["top", "right", "bottom", "left"].some(
					(side) => deviceSize?.[side] !== undefined
				);

				if (hasSizeValues) {
					const sizeUnit = deviceSize?.unit ?? "px";
					const sides = [
						`${deviceSize?.top ?? 0}${sizeUnit}`,
						`${deviceSize?.right ?? 0}${sizeUnit}`,
						`${deviceSize?.bottom ?? 0}${sizeUnit}`,
						`${deviceSize?.left ?? 0}${sizeUnit}`,
					];
					borderCSS += `border-width: ${sides.join(" ")};`;
				}
			}

			if (radius?.[device]) {
				const radiusUnit = radius[device]?.unit ?? "px";
				const sides = [
					`${radius[device]?.top ?? 0}${radiusUnit}`,
					`${radius[device]?.right ?? 0}${radiusUnit}`,
					`${radius[device]?.bottom ?? 0}${radiusUnit}`,
					`${radius[device]?.left ?? 0}${radiusUnit}`,
				];
				if (!sides.every((side) => `0${radiusUnit}` === side)) {
					borderCSS += `border-radius: ${sides.join(" ")};`;
				}
			}

			if (borderCSS) {
				tempCSS[device].push(borderCSS);
			}
		}

		Object.keys(css).forEach((type) => {
			if (tempCSS?.[type]?.length > 0) {
				css[type].push(`${selector}{ ${tempCSS[type].join("")} }`);
			}
		});
	}

	return css;
};

export default borderCSS;
