import { Placeholder } from "@wordpress/components";
import { useSelect } from "@wordpress/data";
import { dateI18n } from "@wordpress/date";
import { decodeEntities } from "@wordpress/html-entities";
import { Fragment } from "@wordpress/element";
import { EditProps } from "blocks/types";
import classnames from "classnames";
import React from "react";

import { useBlockStyle } from "../../hooks";

import { useClientId, useCopyPasteStyles, useDeviceType } from "@blocks/hooks";

import { useBlockProps } from "@wordpress/block-editor";
import { Icon } from "../../components";
import "../assets/sass/blocks/grid-module/style.scss";
import InspectorControls from "./components/InspectorControls";
import {
	cn,
	EMPTY_ARRAY,
	getPostExcerptWords,
	getWPDateSettings,
} from "@blocks/utils";
import { upperFirst } from "lodash";

const Edit: React.ComponentType<EditProps<any>> = (props) => {
	const {
		className,
		attributes: {
			hoverAnimation,

			layout,
			layout1AdvancedStyle,
			layout2AdvancedStyle,
			category,
			tag,
			offset,
			orderBy,
			orderType,
			authorName,
			excludedCategory,
			postType,
			column,
			size,
			label,
			enableHeading,
			headingLayout,
			headingLayout1AdvancedStyle,
			headingLayout2AdvancedStyle,
			headingLayout3AdvancedStyle,
			headingLayout4AdvancedStyle,
			headingLayout5AdvancedStyle,
			headingLayout6AdvancedStyle,
			headingLayout7AdvancedStyle,
			headingLayout8AdvancedStyle,
			headingLayout9AdvancedStyle,

			postCount,
			enableCategory,
			enableComment,
			categoryPosition,

			postTitleMarkup,

			metaPosition,
			enablePostTitle,
			enableAuthor,
			enableDate,
			enableReadTime,
			enableViewCount,
			enableIcon,

			separatorType,

			excerptLimit,
			enableExcerpt,
			enableReadMore,
			readMoreText,

			enableViewMore,
			viewMoreText,
			enableViewMoreIcon,
			viewMoreIcon,
			viewMoreLink,
			viewButtonPosition,

			enablePagination,

			enableNumberList,
			numberLayout,
			numberPosition,

			enablePostBoxBorder,
			enablePostTitleBorder,

			hideOnDesktop,
			page,
		},
		setAttributes,
	} = props;

	const { clientId } = useClientId(props);
	const { deviceType } = useDeviceType();
	const { CopyPasterStyleBlockControl } = useCopyPasteStyles();
	const { Style } = useBlockStyle({
		blockName: "grid-module",
		clientId,
		attributes: props.attributes,
		deviceType,
	});

	// @ts-ignore
	const authors = useSelect((select) => {
		const { getUsers } = select("core") as any;
		return getUsers({ per_page: -1 });
	}) as any[];

	const authorOptions = authors
		? authors.map((author) => ({
				value: author?.id.toString(),
				label: author?.name,
		  }))
		: [];

	const postTypeOptions = useSelect((select) => {
		const { getPostTypes } = select("core") as any;
		const { getCurrentPostType, getCurrentPostId } = select(
			"core/editor"
		) as any;

		const allPostTypes = getPostTypes({ per_page: -1 }) || [];
		const post = (select("core") as any).getEditedEntityRecord(
			"postType",
			getCurrentPostType(),
			getCurrentPostId()
		);
		const currentPostType = post?.type;
		const meta = post?.meta?._mzb_template;

		if (currentPostType === "mzb-builder-template") {
			return allPostTypes
				.filter((type: any) =>
					["post", "mzb-builder"].includes(type.slug)
				)
				.map((type: any) => {
					if (type.slug === "mzb-builder" && meta) {
						return {
							value: type.slug,
							label: `${upperFirst(meta)} Builder`,
						};
					}
					return {
						value: type.slug,
						label: type.name || type.slug,
					};
				});
		}

		return allPostTypes
			.filter((type: any) => type.slug !== "mzb-builder-template")
			.map((type: any) => ({
				value: type.slug,
				label: type.name || type.slug,
			}));
	}, []);

	const { posts, numberOfPosts, categories, tags } = useSelect(
		(select) => {
			const {
				getEntityRecords,
				getEntityRecordsTotalItems,
				getEditedEntityRecord,
			} = select("core") as any;
			const { getCurrentPostType, getCurrentPostId } = select(
				"core/editor"
			) as any;

			const currentPost = getEditedEntityRecord(
				"postType",
				getCurrentPostType(),
				getCurrentPostId()
			);
			const isTemplate = currentPost?.type === "mzb-builder-template";
			const isArchive = currentPost?.type === "archive";
			const isSearch = currentPost?.type === "search";

			const selectedPostType = isTemplate ? "post" : postType || "post";

			const shouldSkipFilters = isTemplate && (isArchive || isSearch);

			const query: any = {
				per_page: postCount,
				offset: offset || 0,
				orderby: orderBy,
				order: orderType,
				author: authorName === "all" ? undefined : authorName,
			};

			if (!shouldSkipFilters) {
				if (category && category !== "all") {
					query.categories = parseInt(category);
				}
				if (tag && tag !== "all") {
					query.tags = tag;
				}
				if (excludedCategory && excludedCategory !== "") {
					query.categories_exclude = excludedCategory;
				}
			}

			const countQuery = {
				per_page: 1,
				_fields: ["id"],
				categories:
					"all" === category || selectedPostType !== "post"
						? undefined
						: parseInt(category),
			};

			// Trigger resolution of the count query so its total can be read
			// from the X-WP-Total header below, without fetching every post.
			getEntityRecords("postType", selectedPostType, countQuery);

			return {
				posts:
					getEntityRecords("postType", selectedPostType, query) ??
					EMPTY_ARRAY,
				numberOfPosts:
					getEntityRecordsTotalItems(
						"postType",
						selectedPostType,
						countQuery
					) ?? 0,
				categories:
					getEntityRecords("taxonomy", "category", {
						per_page: -1,
					}) ?? EMPTY_ARRAY,
				tags:
					getEntityRecords("taxonomy", "post_tag", {
						per_page: -1,
					}) ?? EMPTY_ARRAY,
			};
		},
		[
			category,
			tag,
			postCount,
			offset,
			orderBy,
			orderType,
			authorName,
			excludedCategory,
			postType,
		]
	);

	const classNames = classnames(
		`mzb-grid-module mzb-grid-module-${clientId}`,
		size && `is-${size}`,
		className,
		hideOnDesktop && "magazine-blocks-hide-on-desktop",
		`mzb-${layout}`,
		{
			[`mzb-${layout1AdvancedStyle}`]: layout === `layout-1`,
			[`mzb-${layout2AdvancedStyle}`]: layout === `layout-2`,
		}
	);

	const blockProps = useBlockProps({ className: classNames });

	const classNames2 = classnames(
		`mzb-posts mzb-post-col--${column || "4"}`,
		enableNumberList && "mzb-number-list",
		numberLayout && `mzb-number-list__${numberLayout}`,
		numberPosition && `mzb-number-list__${numberPosition}`
	);

	const NumberedPagination = ({
		totalPages,
		currentPage,
		onPageChange,
	}: {
		totalPages: number;
		currentPage: number;
		onPageChange: (val: number) => void;
	}) => {
		if (totalPages < 2) {
			return null; // Don't render pagination if there's only one page
		}

		const range = 2;
		const pages: Array<number | "ellipsis"> = [1];

		if (currentPage > range + 2) {
			pages.push("ellipsis");
		}

		for (
			let i = Math.max(2, currentPage - range);
			i <= Math.min(totalPages - 1, currentPage + range);
			i++
		) {
			pages.push(i);
		}

		if (currentPage < totalPages - range - 1) {
			pages.push("ellipsis");
		}

		pages.push(totalPages);

		const goToPage = (
			event: React.MouseEvent<HTMLAnchorElement>,
			page: number
		) => {
			event.preventDefault();
			onPageChange(page);
		};

		return (
			<ul className="mzb-pagination-numbers">
				{currentPage > 1 && (
					<li className="page-item prev">
						<a
							className="page-link"
							href="#"
							onClick={(event) =>
								goToPage(event, currentPage - 1)
							}
						>
							<Icon name="arrowLeft" />
						</a>
					</li>
				)}
				{pages.map((page, index) =>
					page === "ellipsis" ? (
						<li
							key={`ellipsis-${index}`}
							className="page-item ellipsis"
						>
							...
						</li>
					) : (
						<li
							key={page}
							className={cn(
								"page-item",
								page === currentPage && "current"
							)}
						>
							<a
								className="page-link"
								href="#"
								onClick={(event) => goToPage(event, page)}
							>
								{page}
							</a>
						</li>
					)
				)}
				{currentPage < totalPages && (
					<li className="page-item next">
						<a
							className="page-link"
							href="#"
							onClick={(event) =>
								goToPage(event, currentPage + 1)
							}
						>
							<Icon name="arrowRight" />
						</a>
					</li>
				)}
			</ul>
		);
	};

	// Fetch the next page of posts
	const loadMorePosts = (nextPage: number) => {
		// Update the block's attributes to trigger a re-render with the next page
		setAttributes({ page: nextPage });
	};

	// Render numbered pagination
	const pagination = (
		<NumberedPagination
			totalPages={Math.ceil(numberOfPosts / postCount)}
			currentPage={page}
			onPageChange={loadMorePosts}
		/>
	);

	const TagName = postTitleMarkup || "h6";

	if (posts !== undefined && posts.length === 0) {
		return (
			<Fragment>
				<InspectorControls
					attributes={props.attributes}
					setAttributes={setAttributes}
					categories={categories}
					tags={tags}
					authorOptions={authorOptions}
					postTypeOptions={postTypeOptions}
				/>
				<CopyPasterStyleBlockControl withBlockControls />
				<Style />
				<div {...blockProps}>
					<Placeholder
						icon={
							<Icon
								type="blockIcon"
								name="gridModule"
								size={24}
							/>
						}
						label="Grid Module"
						instructions="No posts found. Please publish posts to display them in this block."
					/>
				</div>
			</Fragment>
		);
	}

	return (
		<Fragment>
			<InspectorControls
				attributes={props.attributes}
				setAttributes={setAttributes}
				categories={categories}
				tags={tags}
				authorOptions={authorOptions}
				postTypeOptions={postTypeOptions}
			/>
			<CopyPasterStyleBlockControl withBlockControls />
			<Style />
			<div {...blockProps}>
				<div
					className={classnames(
						`mzb-post-heading mzb-${headingLayout}`,
						{
							[`mzb-${headingLayout1AdvancedStyle}`]:
								headingLayout === `heading-layout-1`,
							[`mzb-${headingLayout2AdvancedStyle}`]:
								headingLayout === `heading-layout-2`,
							[`mzb-${headingLayout3AdvancedStyle}`]:
								headingLayout === `heading-layout-3`,
							[`mzb-${headingLayout4AdvancedStyle}`]:
								headingLayout === `heading-layout-4`,
							[`mzb-${headingLayout5AdvancedStyle}`]:
								headingLayout === `heading-layout-5`,
							[`mzb-${headingLayout6AdvancedStyle}`]:
								headingLayout === `heading-layout-6`,
							[`mzb-${headingLayout7AdvancedStyle}`]:
								headingLayout === `heading-layout-7`,
							[`mzb-${headingLayout8AdvancedStyle}`]:
								headingLayout === `heading-layout-8`,
							[`mzb-${headingLayout9AdvancedStyle}`]:
								headingLayout === `heading-layout-9`,
						}
					)}
				>
					{enableHeading === true && (
						<h2 className="mzb-heading-text"> {label} </h2>
					)}
					{viewButtonPosition === "top" && enableViewMore && (
						<div className="mzb-view-more">
							{/*eslint-disable-next-line react/jsx-no-target-blank */}
							<a
								href={"#"}
								target={
									viewMoreLink?.newTab ? "_blank" : "_self"
								}
								rel={[
									viewMoreLink?.newTab
										? "noreferrer noopener"
										: "",
									viewMoreLink?.noFollow ? "nofollow" : "",
								]
									.filter(Boolean)
									.join(" ")}
							>
								<p>{viewMoreText}</p>
								{enableViewMoreIcon && (
									<Icon
										type="frontendIcon"
										name={viewMoreIcon}
										size={24}
									/>
								)}
							</a>
						</div>
					)}
				</div>
				{
					<div className={classNames2}>
						<Fragment>
							{(posts || []).map((post: any, idx: number) => {
								const maxWords = excerptLimit;
								const excerpt = getPostExcerptWords(
									post,
									maxWords
								);
								return (
									<div
										className={`mzb-post ${
											enablePostBoxBorder
												? "mzb-post-box-border"
												: ""
										}`}
										key={idx}
									>
										{post
											?.magazine_blocks_featured_image_url
											?.full?.[0] && (
											<div
												className={`mzb-featured-image ${hoverAnimation} ${
													layout === "layout-2" &&
													categoryPosition ===
														"in-image" &&
													"mzb-category--inside-image"
												}`}
											>
												<img
													src={
														post
															?.magazine_blocks_featured_image_url
															?.full[0]
													}
												/>
												<div className="mzb-overlay" />
												{(enableCategory ||
													enableComment) &&
													layout === "layout-2" &&
													categoryPosition ===
														"in-image" && (
														<div className="mzb-post-meta">
															{enableCategory && (
																<span
																	className="mzb-post-categories"
																	dangerouslySetInnerHTML={{
																		__html: post?.magazine_blocks_category,
																	}}
																/>
															)}
															{enableComment && (
																<span className="mzb-comments-link">
																	<Icon
																		type="frontendIcon"
																		name="commentIcon"
																		size={
																			24
																		}
																	/>{" "}
																	{
																		post?.magazine_blocks_comment
																	}
																</span>
															)}
														</div>
													)}
											</div>
										)}
										{(enableDate ||
											enableAuthor ||
											enablePostTitle ||
											enableCategory ||
											enableComment ||
											enableReadTime ||
											enableViewCount) && (
											<>
												<div className="mzb-post-content">
													{(enableCategory ||
														enableComment) &&
														(layout !==
															"layout-2" ||
															categoryPosition ===
																"out-image") && (
															<div className="mzb-post-meta">
																{enableCategory && (
																	<span
																		className="mzb-post-categories"
																		dangerouslySetInnerHTML={{
																			__html: post?.magazine_blocks_category,
																		}}
																	/>
																)}
																{enableComment && (
																	<span className="mzb-comments-link">
																		<Icon
																			type="frontendIcon"
																			name="commentIcon"
																			size={
																				24
																			}
																		/>{" "}
																		{
																			post?.magazine_blocks_comment
																		}
																	</span>
																)}
															</div>
														)}
													{metaPosition ===
														"bottom" && (
														<>
															{enablePostTitle ===
																true && (
																<TagName
																	className={`mzb-post-title ${
																		enablePostTitleBorder
																			? "mzb-post-title-border"
																			: ""
																	}`}
																>
																	<a
																		href={
																			"#"
																		}
																	>
																		{decodeEntities(
																			post
																				?.title
																				?.rendered ||
																				"(Untitled)"
																		)}
																	</a>
																</TagName>
															)}
															{(enableAuthor ||
																enableDate ||
																enableReadTime ||
																enableViewCount) && (
																<>
																	<div
																		className={cn(
																			"mzb-post-entry-meta",
																			separatorType &&
																				`mzb-meta-separator--${separatorType}`
																		)}
																	>
																		{enableAuthor ===
																			true && (
																			<span className="mzb-post-author">
																				{enableIcon ===
																					true && (
																					<img
																						className="author-display-image"
																						src={
																							post?.magazine_blocks_author_image
																						}
																					/>
																				)}
																				<a
																					href={
																						"#"
																					}
																				>
																					{" "}
																					{
																						post
																							?.magazine_blocks_author
																							?.display_name
																					}{" "}
																				</a>
																			</span>
																		)}

																		{enableDate ===
																			true && (
																			<span className="mzb-post-date">
																				{enableIcon ===
																					true && (
																					<Icon
																						type="blockIcon"
																						name="calendar"
																						size={
																							24
																						}
																					/>
																				)}
																				<a href="#">
																					{" "}
																					{dateI18n(
																						getWPDateSettings()
																							.formats
																							.date,
																						post?.date_gmt,
																						undefined
																					)}{" "}
																				</a>
																			</span>
																		)}
																		{enableReadTime ===
																			true && (
																			<span className="mzb-post-read-time">
																				{enableIcon ===
																					true && (
																					<Icon name="clock" />
																				)}
																				<span>
																					{
																						post?.magazineBlocksPostReadTime
																					}{" "}
																					min
																					read
																				</span>
																			</span>
																		)}
																		{enableViewCount ===
																			true && (
																			<span className="mzb-post-view-count">
																				{enableIcon ===
																					true && (
																					<Icon
																						name="eyeO"
																						fill="#fff"
																					/>
																				)}
																				<span>
																					{post?.magazineBlocksPostViewCount ||
																						0}{" "}
																					views
																				</span>
																			</span>
																		)}
																	</div>
																</>
															)}
														</>
													)}
													{metaPosition === "top" &&
														(enableAuthor ||
															enableDate) && (
															<>
																<div
																	className={cn(
																		"mzb-post-entry-meta",
																		separatorType &&
																			`mzb-meta-separator--${separatorType}`
																	)}
																>
																	{enableAuthor ===
																		true && (
																		<span className="mzb-post-author">
																			{enableIcon ===
																				true && (
																				<img
																					className="author-display-image"
																					src={
																						post?.magazine_blocks_author_image
																					}
																				/>
																			)}
																			<a
																				href={
																					"#"
																				}
																			>
																				{" "}
																				{
																					post
																						?.magazine_blocks_author
																						?.display_name
																				}{" "}
																			</a>
																		</span>
																	)}

																	{enableDate ===
																		true && (
																		<span className="mzb-post-date">
																			{enableIcon ===
																				true && (
																				<Icon
																					type="blockIcon"
																					name="calendar"
																					size={
																						24
																					}
																				/>
																			)}
																			<a href="#">
																				{" "}
																				{dateI18n(
																					getWPDateSettings()
																						.formats
																						.date,
																					post?.date_gmt,
																					undefined
																				)}{" "}
																			</a>
																		</span>
																	)}
																	{enableReadTime ===
																		true && (
																		<span className="mzb-post-read-time">
																			{enableIcon ===
																				true && (
																				<Icon name="clock" />
																			)}
																			<span>
																				{
																					post?.magazineBlocksPostReadTime
																				}{" "}
																				min
																				read
																			</span>
																		</span>
																	)}
																	{enableViewCount ===
																		true && (
																		<span className="mzb-post-view-count">
																			{enableIcon ===
																				true && (
																				<Icon
																					name="eyeO"
																					fill="#fff"
																				/>
																			)}
																			<span>
																				{post?.magazineBlocksPostViewCount ||
																					0}{" "}
																				views
																			</span>
																		</span>
																	)}
																</div>

																{enablePostTitle ===
																	true && (
																	<TagName
																		className={`mzb-post-title ${
																			enablePostTitleBorder
																				? "mzb-post-title-border"
																				: ""
																		}`}
																	>
																		<a
																			href={
																				"#"
																			}
																		>
																			{decodeEntities(
																				post
																					?.title
																					?.rendered ||
																					"(Untitled)"
																			)}
																		</a>
																	</TagName>
																)}
															</>
														)}
													{(enableExcerpt ||
														enableReadMore) && (
														<div className="mzb-entry-content">
															{enableExcerpt && (
																<div
																	className="mzb-entry-summary"
																	dangerouslySetInnerHTML={{
																		__html: excerpt,
																	}}
																/>
															)}
															{enableReadMore && (
																<div className="mzb-read-more">
																	<a
																		href={
																			"#"
																		}
																	>
																		{
																			readMoreText
																		}
																	</a>
																</div>
															)}
														</div>
													)}
												</div>
											</>
										)}
									</div>
								);
							})}
						</Fragment>
					</div>
				}
				{enablePagination && pagination}
				{viewButtonPosition === "bottom" && enableViewMore && (
					<div className="mzb-view-more">
						{/*eslint-disable-next-line react/jsx-no-target-blank */}
						<a
							href={"#"}
							target={viewMoreLink?.newTab ? "_blank" : "_self"}
							rel={[
								viewMoreLink?.newTab
									? "noreferrer noopener"
									: "",
								viewMoreLink?.noFollow ? "nofollow" : "",
							]
								.filter(Boolean)
								.join(" ")}
						>
							<p>{viewMoreText}</p>
							{enableViewMoreIcon && (
								<Icon
									type="frontendIcon"
									name={viewMoreIcon}
									size={24}
								/>
							)}
						</a>
					</div>
				)}
			</div>
		</Fragment>
	);
};

export default Edit;
