import { addFilter } from "@wordpress/hooks";
import { withResponsiveHidePreview } from "../hoc";

const addResponsiveHidePreview = () => {
	addFilter(
		"editor.BlockListBlock",
		"magazine-blocks/with-responsive-hide-preview",
		withResponsiveHidePreview
	);
};

export default addResponsiveHidePreview;
