import { subscribe } from "@wordpress/data";
import domReady from "@wordpress/dom-ready";

let guardedDocument: Document | null = null;

const preventPreviewNavigation = (event: MouseEvent) => {
	const target = event.target as HTMLElement | null;
	const anchor = target?.closest("a");
	if (anchor && anchor.closest('[class*="mzb-"]')) {
		event.preventDefault();
	}
};

/**
 * Magazine Blocks post-listing blocks render placeholder links (title, author,
 * date, read more, view-more, etc.) to preview frontend markup while editing.
 * Some of these carry real hrefs (post permalinks, user-configured "view more"
 * URLs). Unlike RichText-controlled links, plain anchors aren't sandboxed by
 * the block editor, so clicking one navigates the editor's own canvas iframe
 * away from the admin origin - which can crash the editor with a SecurityError
 * once the iframe becomes cross-origin and core cleanup code tries to detach
 * listeners from its window. Blocks navigation for every anchor inside an
 * mzb- block, regardless of its href.
 */
const disablePreviewLinkNavigation = () => {
	domReady(() => {
		subscribe(() => {
			const iframe = document.querySelector(
				'iframe[name="editor-canvas"]'
			) as HTMLIFrameElement | null;
			const doc = iframe?.contentDocument;
			if (!doc || doc === guardedDocument) return;
			guardedDocument = doc;
			doc.addEventListener("click", preventPreviewNavigation, true);
		});
	});
};

export default disablePreviewLinkNavigation;
