import { BlockInstance } from "@wordpress/blocks";

/**
 * Resets demo-only category/tag filters on imported library template blocks.
 * Library templates carry taxonomy IDs from ThemeGrill's demo site; those IDs don't exist on the importing site, so filtered blocks would otherwise render empty. Only string-valued `category`/`tag` attributes are reset, since some blocks (e.g. Category) reuse the same attribute names for a numeric single-term reference rather than an "all"-or-ID filter.
 * @param blocks - Parsed block tree to sanitize, as returned by `@wordpress/blocks` `parse()`.
 * @returns The same tree with taxonomy filters reset to their unfiltered defaults where applicable.
 */
const resetTemplateTaxonomyFilters = (
	blocks: Array<BlockInstance>
): Array<BlockInstance> =>
	blocks.map((block) => ({
		...block,
		attributes: {
			...block.attributes,
			...(typeof block.attributes.category === "string" && {
				category: "all",
			}),
			...(typeof block.attributes.tag === "string" && { tag: "all" }),
			...(Array.isArray(block.attributes.excludedCategory) && {
				excludedCategory: [],
			}),
			...(Array.isArray(block.attributes.excludedTag) && {
				excludedTag: [],
			}),
		},
		innerBlocks: resetTemplateTaxonomyFilters(block.innerBlocks ?? []),
	}));

export default resetTemplateTaxonomyFilters;
