import { registerBlocks } from "./blocks";
import "./editor.scss";
import {
	addPluginSidebar,
	addResponsiveHidePreview,
	addShortcutSidebar,
	addToolbarLibraryButton,
	autoRecoverBlocks,
	disableBlocks,
	disablePreviewLinkNavigation,
	setSectionDefaultWidth,
	updateBlockAttributes,
	updateBlockCategoryIcon,
} from "./helpers";
import { GlobalStylesProcessor } from "./hooks/useGlobalStyles";
import "./store/styles-store";
import { localized } from "./utils";
import "./helpers/change-editor-logo-url";
new GlobalStylesProcessor(localized.configs["global-styles"]).process();

addShortcutSidebar();
// disable blocks.
disableBlocks();

addResponsiveHidePreview(); // Grey out blocks hidden on the previewed device.

setSectionDefaultWidth();
addToolbarLibraryButton(); // Add toolbar library button.
disablePreviewLinkNavigation(); // Stop placeholder links from navigating the editor canvas.

// Register blocks.
registerBlocks();

updateBlockAttributes(); // update old attributes.
updateBlockCategoryIcon(); // Update Magazine Blocks category icon.
autoRecoverBlocks(); // Auto recover blocks in widget/customize screen.
addPluginSidebar();
new GlobalStylesProcessor(localized.configs["global-styles"]).process();
