import { useClientId, useCopyPasteStyles, useDeviceType } from "@blocks/hooks";
import { useBlockProps } from "@wordpress/block-editor";
import { Button, Flex, FlexItem } from "@wordpress/components";
import { select, useSelect, withSelect } from "@wordpress/data";
import { Fragment, useMemo } from "@wordpress/element";
import { _n } from "@wordpress/i18n";
import { EditProps } from "blocks/types";
import classnames from "classnames";
import React from "react";
import { useBlockStyle } from "../../hooks";
import { EMPTY_ARRAY } from "../../utils";
import "../assets/sass/blocks/category-list/style.scss";
import InspectorControls from "./components/InspectorControls";
import { Icon } from "@blocks/components";
import useGlobalStyles from "../../hooks/useGlobalStyles";

interface Props extends EditProps<any> {
	categories: Array<any>;
	posts: Array<any>;
	tags: Array<any>;
	numberOfPosts: number;
	page: number;
	author: Array<any>;
}

const getPostCountLabel = (count: number) =>
	_n("Post", "Posts", count, "magazine-blocks");

const Edit: React.ComponentType<Props> = (props) => {
	const {
		className,
		attributes: {
			label,
			layout,
			layout1AdvancedStyle,
			layout2AdvancedStyle,
			layout3AdvancedStyle,
			postBoxStyle,
			listIcon,

			category,
			postCount,

			categoryCount,

			enableHeading,
			headingLayout,
			headingLayout1AdvancedStyle,
			headingLayout2AdvancedStyle,
			headingLayout3AdvancedStyle,
			headingLayout4AdvancedStyle,
			headingLayout5AdvancedStyle,
			size,
			hideOnDesktop,

			enableIcon,
			categoryArrow,
			categoryTitleMarkup,
		},
		setAttributes,
		categories,
		tags,
		numberOfPosts,
		page,
	} = props;

	const { clientId } = useClientId(props);
	const { deviceType } = useDeviceType();
	const { CopyPasterStyleBlockControl } = useCopyPasteStyles();
	const TagName = categoryTitleMarkup || "h6";
	const { Style } = useBlockStyle({
		blockName: "category-list",
		clientId,
		attributes: props.attributes,
		deviceType,
	});

	// @ts-ignore
	const authors = useSelect((select) => {
		const { getUsers } = select("core") as any;
		return getUsers({ per_page: -1 });
	}) as any[];

	const authorOptions = authors
		? authors.map((author) => ({
				value: author.id.toString(),
				label: author.name,
		  }))
		: [];

	const currentCategoryIndex = useMemo(() => {
		return categories
			? categories.findIndex((cat) => cat.id === parseInt(category))
			: -1; // Use -1 or another appropriate default value
	}, [category, categories]);

	const activeCategories = useMemo(() => {
		return (categories || []).filter((cat) => cat.count > 0);
	}, [categories]);

	const featureImage = (id: number) => {
		const post = select("core").getEntityRecords("postType", "post", {
			per_page: 1,
			categories: id,
		});
		return post?.[0]?.magazine_blocks_featured_image_url?.full?.[0] || null;
	};

	const classNames = classnames(
		`mzb-category-list mzb-category-list-${clientId}`,
		size && `is-${size}`,
		className,
		hideOnDesktop && "magazine-blocks-hide-on-desktop"
	);

	const classNames2 = classnames(`mzb-posts mzb-${layout}`, {
		[`mzb-${layout1AdvancedStyle}`]: layout === `layout-1`,
		[`mzb-${layout2AdvancedStyle}`]: layout === `layout-2`,
		[`mzb-${layout3AdvancedStyle}`]: layout === `layout-3`,
		[`separator`]:
			postBoxStyle &&
			layout === `layout-3` &&
			layout3AdvancedStyle === "layout-3-style-1",
	});

	const classNames3 = classnames(`mzb-post-heading mzb-${headingLayout}`, {
		[`mzb-${headingLayout1AdvancedStyle}`]:
			headingLayout === `heading-layout-1`,
		[`mzb-${headingLayout2AdvancedStyle}`]:
			headingLayout === `heading-layout-2`,
		[`mzb-${headingLayout3AdvancedStyle}`]:
			headingLayout === `heading-layout-3`,
		[`mzb-${headingLayout4AdvancedStyle}`]:
			headingLayout === `heading-layout-4`,
		[`mzb-${headingLayout5AdvancedStyle}`]:
			headingLayout === `heading-layout-5`,
	});

	const blockProps = useBlockProps({ className: classNames });

	// Access the localized variable
	const categoryColors = (window as any).colormag_category_colors;
	const overrideCategory = (window as any).colormag_category_color_override;

	const getCategoryColor = (categoryId: number) => {
		return categoryColors && categoryColors[categoryId]
			? categoryColors[categoryId]
			: "";
	};

	const NumberedPagination = ({
		totalPages,
		currentPage,
		onPageChange,
	}: {
		totalPages: number;
		currentPage: number;
		onPageChange: (val: number) => void;
	}) => {
		if (totalPages < 2) {
			return null; // Don't render pagination if there's only one page
		}

		const pages = Array.from(
			{ length: totalPages },
			(_, index) => index + 1
		);

		return (
			<Flex>
				{/* eslint-disable-next-line */}
				{pages.map((page) => (
					<FlexItem key={page}>
						<Button
							variant={
								page === currentPage ? "primary" : undefined
							}
							onClick={() => onPageChange(page)}
						>
							{page}
						</Button>
					</FlexItem>
				))}
			</Flex>
		);
	};

	// Fetch the next page of posts
	const loadMorePosts = (nextPage: number) => {
		// Update the block's attributes to trigger a re-render with the next page
		setAttributes({ page: nextPage });
	};

	// Render numbered pagination
	const pagination = (
		<NumberedPagination
			totalPages={Math.ceil(numberOfPosts / postCount)}
			currentPage={page}
			onPageChange={loadMorePosts}
		/>
	);

	const { styles } = useGlobalStyles();
	const categoriesColor = styles?.categories_color; // This is your categories_color array

	return (
		<Fragment>
			<InspectorControls
				attributes={props.attributes}
				setAttributes={setAttributes}
				categories={categories}
				tags={tags}
				authorOptions={authorOptions}
			/>
			<CopyPasterStyleBlockControl withBlockControls />
			<Style />
			<div {...blockProps}>
				{enableHeading === true && (
					<div className={classNames3}>
						<h2 className="mzb-heading-text"> {label} </h2>
					</div>
				)}
				<div className={classNames2}>
					<Fragment>
						{activeCategories
							.slice(0, categoryCount)
							.map(({ id, name, count, link, slug }, idx) => {
								if (count > 0) {
									const imageUrl = featureImage(id);

									return (
										<div className="mzb-post" key={idx}>
											{"layout-1-style-2" ===
												layout1AdvancedStyle ||
											"layout-2-style-2" ===
												layout2AdvancedStyle ||
											"layout-2-style-3" ===
												layout2AdvancedStyle ? (
												<>
													{"layout-1-style-2" ===
														layout1AdvancedStyle && (
														<>
															<div
																className="mzb-title-wrapper"
																style={
																	imageUrl
																		? {
																				backgroundImage: `url(${imageUrl})`,
																		  }
																		: undefined
																}
															>
																<div className="mzb-title">
																	<TagName
																		className={`mzb-post-categories ${slug}`}
																	>
																		{""}
																		<a
																			href={
																				"#"
																			}
																		>
																			{
																				name
																			}
																		</a>
																	</TagName>
																	<div className="mzb-post-count-wrapper">
																		<div className="mzb-post-count">
																			{""}
																			<a
																				href={
																					"#"
																				}
																			>
																				{
																					count
																				}
																				<span className="mzb-post-count-text">
																					{" "}
																					{getPostCountLabel(
																						count
																					)}
																				</span>
																			</a>
																		</div>
																	</div>
																</div>
															</div>
														</>
													)}
													{"layout-2-style-2" ===
														layout2AdvancedStyle && (
														<>
															<div
																className="mzb-title-wrapper"
																style={
																	imageUrl
																		? {
																				backgroundImage: `url(${imageUrl})`,
																		  }
																		: undefined
																}
															>
																<div className="mzb-title">
																	<TagName
																		className={`mzb-post-categories ${slug}`}
																	>
																		{""}
																		<a
																			href={
																				"#"
																			}
																		>
																			{
																				name
																			}
																		</a>
																	</TagName>
																	<div className="mzb-post-count-wrapper">
																		<div className="mzb-post-count">
																			{""}
																			<a
																				href={
																					"#"
																				}
																			>
																				{
																					count
																				}
																				<span className="mzb-post-count-text">
																					{" "}
																					{getPostCountLabel(
																						count
																					)}
																				</span>
																			</a>
																		</div>
																	</div>
																</div>
																<div className="mzb-overlay"></div>
																{categoryArrow &&
																	"" !==
																		categoryArrow.icon &&
																	categoryArrow.enable && (
																		<div className="mzb-list-icon">
																			<Icon
																				type="frontendIcon"
																				name={
																					categoryArrow.icon
																				}
																			/>
																		</div>
																	)}
															</div>
														</>
													)}
													{"layout-2-style-3" ===
														layout2AdvancedStyle && (
														<>
															<div
																className="mzb-title-wrapper"
																style={
																	imageUrl
																		? {
																				backgroundImage: `url(${imageUrl})`,
																		  }
																		: undefined
																}
															>
																<div className="mzb-overlay"></div>
															</div>
															<div className="mzb-title-with-icon">
																<div className="mzb-title">
																	<TagName
																		className={`mzb-post-categories ${slug}`}
																	>
																		{""}
																		<a
																			href={
																				"#"
																			}
																		>
																			{
																				name
																			}
																		</a>
																	</TagName>
																	<div className="mzb-post-count-wrapper">
																		<div className="mzb-post-count">
																			{""}
																			<a
																				href={
																					"#"
																				}
																			>
																				{
																					count
																				}
																				<span className="mzb-post-count-text">
																					{" "}
																					{getPostCountLabel(
																						count
																					)}
																				</span>
																			</a>
																		</div>
																	</div>
																</div>
																{categoryArrow &&
																	"" !==
																		categoryArrow.icon &&
																	categoryArrow.enable && (
																		<div className="mzb-list-icon">
																			<Icon
																				type="frontendIcon"
																				name={
																					categoryArrow.icon
																				}
																			/>
																		</div>
																	)}
															</div>
														</>
													)}
												</>
											) : (
												<>
													<div
														className="mzb-title-wrapper"
														style={
															imageUrl
																? {
																		backgroundImage: `url(${imageUrl})`,
																  }
																: undefined
														}
													>
														<TagName
															className={`mzb-post-categories ${slug}`}
														>
															{listIcon &&
																"" !==
																	listIcon.icon &&
																"layout-3" ===
																	layout &&
																listIcon.enable && (
																	<span className="mzb-list-icon">
																		<Icon
																			type="frontendIcon"
																			name={
																				listIcon.icon
																			}
																		/>
																	</span>
																)}
															<a href={"#"}>
																{name}
															</a>
														</TagName>
													</div>
													<div className="mzb-post-count-wrapper">
														<div className="mzb-post-count">
															{""}
															{listIcon &&
															"layout-3" ===
																layout &&
															listIcon.enable ? (
																<>
																	({""}
																	<a
																		href={
																			"#"
																		}
																	>
																		{count}
																	</a>
																	{""})
																</>
															) : (
																<a href={"#"}>
																	{count}
																</a>
															)}

															<a href={"#"}>
																{" "}
																{getPostCountLabel(
																	count
																)}{" "}
															</a>
														</div>
													</div>
												</>
											)}
										</div>
									);
								}
							})}
					</Fragment>
				</div>
			</div>
		</Fragment>
	);
};

// @ts-ignore
export default withSelect((select, props) => {
	const { getEntityRecords } = select("core");
	const {
		attributes: {
			category,
			tag,
			postCount,
			order,
			orderBy,
			orderType,
			authorName,
			excludedCategory,
			page,
		},
	} = props;
	const query = {
		order,
	};

	return {
		posts: getEntityRecords("postType", "post", {
			...query,
			categories:
				category && "all" !== category ? parseInt(category) : undefined,
			tags: "all" === tag ? undefined : tag,
			per_page: postCount,
			page,
			orderby: orderBy,
			order: orderType,
			author: authorName,
			categories_exclude: "" === excludedCategory ? [] : excludedCategory,
		}),
		numberOfPosts:
			getEntityRecords("postType", "post", {
				per_page: -1,
				categories:
					category && "all" !== category
						? parseInt(category)
						: undefined,
			})?.length || 0,
		categories:
			getEntityRecords("taxonomy", "category", { per_page: -1 }) ??
			EMPTY_ARRAY,
		tags:
			getEntityRecords("taxonomy", "post_tag", { per_page: -1 }) ??
			EMPTY_ARRAY,
	};
})(Edit);
